import { useState, useRef, useCallback, useMemo } from 'react';
import uniqueId from 'lodash/uniqueId';
import { isNil } from 'lodash';
import { useConst } from '@fiverr-private/hooks';
import { getIdByLabel } from '../useProgress/helpers';
import useProgress from '../useProgress';
import useStepsProps from '../useStepsProps';
import type { IUseStepperStepperProps, IUseStepper } from './types';
import { getCompletedStepsInitial, getNextStep, getPrevStep } from './helpers';

const useStepper = ({
  steps,
  initialStep = 0,
  currentStep: controlledStep,
  onCurrentStepChanged,
  orientation = 'horizontal',
  autoSelect = true,
  stepStrategy = 'cyclic',
  includeOptional = true,
}: IUseStepper) => {
  const completedStepsInitial = useConst(() => getCompletedStepsInitial(steps));
  const [currentStep, setCurrentStep] = useState(initialStep);
  const [completedSteps, setCompletedSteps] = useState(completedStepsInitial);
  const completedStepsRef = useRef({});
  const actualStep = controlledStep ?? currentStep;
  const totalSteps = steps.length;
  const stepperRef = useRef(uniqueId('steps-'));
  const progressRef = useRef(`${stepperRef.current}-progress`);
  const hasNextStep = actualStep < totalSteps - 1;
  const hasPreviousStep = actualStep > 0;

  const navigateSteps = useCallback(
    (targetStep: number) => {
      const nextStep = targetStep;

      if (nextStep >= 0 && nextStep < totalSteps) {
        setCurrentStep(nextStep);
        onCurrentStepChanged?.(nextStep);
      }
    },
    [totalSteps, onCurrentStepChanged]
  );

  const setStep = useCallback(
    (step: number) => {
      if (!steps[step]?.disabled) {
        navigateSteps(step);
      }
    },
    [navigateSteps, steps]
  );

  const reset = useCallback(() => {
    setCompletedSteps(completedStepsInitial);
    completedStepsRef.current = completedStepsInitial;
    setCurrentStep(initialStep);
  }, [completedStepsInitial, initialStep]);

  const stepperProps: IUseStepperStepperProps = useMemo(
    () => ({
      role: 'tablist',
      'aria-orientation': orientation,
      id: stepperRef.current,
      currentStep,
      stepStrategy,
      orientation,
      completedSteps,
    }),
    [completedSteps, currentStep, orientation, stepStrategy]
  );

  const { stepsProps } = useStepsProps({
    includeOptional,
    steps,
    completedStepsRef,
    stepStrategy,
    actualStep,
    completedSteps,
    stepperRef,
    orientation,
    navigateSteps,
    autoSelect,
    setCompletedSteps,
    setStep,
  });
  const { progressPercent } = useProgress({ stepsProps, includeOptional });

  const nextStep = useCallback(() => {
    const nextStep = getNextStep({ stepStrategy, actualStep, steps, completedStepsRef });
    if (!isNil(nextStep)) {
      navigateSteps(nextStep);
    }
  }, [actualStep, navigateSteps, stepStrategy, steps]);

  const prevStep = useCallback(() => {
    const prevStep = getPrevStep({ stepStrategy, steps, actualStep });
    if (!isNil(prevStep)) {
      navigateSteps(prevStep);
    }
  }, [actualStep, navigateSteps, stepStrategy, steps]);

  const setStepCompleteState = (isCompleted: boolean, stepIndex?: number) => {
    const targetStepIndex = stepIndex ?? actualStep;
    const hashId = getIdByLabel(steps[targetStepIndex].label);

    completedStepsRef.current = {
      ...completedStepsRef.current,
      [hashId]: isCompleted,
    };
    setCompletedSteps(completedStepsRef.current);
  };

  const progressProps = useMemo(
    () => ({
      'aria-valuenow': actualStep,
      'aria-valuemin': 0,
      'aria-valuemax': totalSteps,
      role: 'progressbar',
      id: progressRef.current,
      progressPercent,
      tabIndex: -1,
    }),
    [actualStep, progressPercent, totalSteps]
  );

  return {
    currentStep: actualStep,
    hasPreviousStep,
    hasNextStep,
    nextStep,
    prevStep,
    setStep,
    stepsProps,
    stepperProps,
    progressProps,
    setStepCompleteState,
    orientation,
    stepStrategy,
    reset,
  };
};

export default useStepper;
