import { useEffect, useMemo, useState } from 'react';

const useProgress = ({ stepsProps, includeOptional }) => {
    const [progressPercent, setProgressPercent] = useState(0);
    const stepsToInclude = useMemo(
        () => (includeOptional ? stepsProps : stepsProps.filter((step) => !step.optional)),
        [includeOptional, stepsProps]
    );

    useEffect(() => {
        const progress = stepsToInclude.reduce((acc, step) => (step.completed ? acc + step.weight : acc), 0);

        setProgressPercent(progress);
    }, [setProgressPercent, stepsProps, stepsToInclude]);

    return {
        progressPercent,
    };
};

export default useProgress;
