import React from 'react';
import { isArray } from 'lodash';
import { childrenIdMatch } from '../utils';
export const excludeChildrenByType = (children, id) => React.Children.toArray(children).filter(child => {
  if (isArray(id)) {
    return !id.some(singleId => childrenIdMatch(child, singleId));
  }
  return !childrenIdMatch(child, id);
});