import { getIdByLabel } from '../useProgress/helpers';

export const NO_NEXT_STEP = -1;

export const stepId = (prefix: string, index: number) => `${prefix}:step-${index}`;
export const getNextNonDisabledStep = (stepsProps, actualStep, isLinearStrategy) => {
    let nextStep = actualStep + 1;

    if (stepsProps[nextStep]?.disabled && !stepsProps[nextStep]?.optional && isLinearStrategy) {
        return null;
    }
    while (stepsProps[nextStep]?.disabled && nextStep < stepsProps.length) {
        nextStep++;
    }

    return nextStep < stepsProps.length ? nextStep : NO_NEXT_STEP;
};

export const getPreviousNonDisabledStep = (stepsProps, actualStep) => {
    let previousStep = actualStep - 1;

    while (stepsProps[previousStep]?.disabled && previousStep >= 0) {
        previousStep--;
    }

    return previousStep >= 0 ? previousStep : NO_NEXT_STEP;
};

export const getNextStep = ({ stepStrategy, actualStep, steps, completedStepsRef }) => {
    const isLinearStrategy = stepStrategy === 'linear' || stepStrategy === 'linear-back';
    const nextNonDisabledStep = getNextNonDisabledStep(steps, actualStep, isLinearStrategy);
    const hasNextEnabledStep = nextNonDisabledStep !== NO_NEXT_STEP;
    const hashId = getIdByLabel(steps[actualStep].label);

    if (
        (completedStepsRef?.current?.[hashId] || steps[actualStep]?.optional) &&
        hasNextEnabledStep &&
        isLinearStrategy
    ) {
        return nextNonDisabledStep;
    }
    if (stepStrategy === 'cyclic') {
        if (!hasNextEnabledStep) {
            return 0;
        } else {
            return nextNonDisabledStep;
        }
    }
};
export const getPrevStep = ({ stepStrategy, steps, actualStep }) => {
    const previousNonDisabledStep = getPreviousNonDisabledStep(steps, actualStep);

    if (stepStrategy === 'linear-back') {
        if (previousNonDisabledStep !== NO_NEXT_STEP) {
            return previousNonDisabledStep;
        }
    }

    if (stepStrategy === 'cyclic') {
        if (previousNonDisabledStep === NO_NEXT_STEP) {
            return steps.length - 1;
        } else {
            return previousNonDisabledStep;
        }
    }
};

export const getCompletedStepsInitial = (steps) => {
    const completedSteps = {};

    steps.forEach((step, index) => {
        if (step.completed === true) {
            completedSteps[index] = true;
        }
    });

    return completedSteps;
};
