import { useCallback, useEffect, useMemo, useRef } from 'react';
import { isNil } from 'lodash';
import { getNextStep, getPrevStep, stepId } from '../useStepper/helpers';
import { getIdByLabel, getWeight } from '../useProgress/helpers';
import { HORIZONTAL_KEYS, SUBMIT_KEYS, VERTICAL_KEYS } from './constants';

const useStepsProps = ({
    includeOptional,
    steps,
    completedStepsRef,
    stepStrategy,
    actualStep,
    completedSteps,
    stepperRef,
    orientation,
    navigateSteps,
    autoSelect,
    setCompletedSteps,
    setStep,
}) => {
    const stepElementsRef = useRef<(HTMLElement | null)[]>([]);
    const stepsToInclude = useMemo(
        () => (includeOptional ? steps : steps.filter((step) => !step.optional)),
        [includeOptional, steps]
    );
    const preStepsProps = useRef(steps);
    const initialWeight = useRef(100 / stepsToInclude.length);
    const totalWeight = useRef(0);

    const handleKeyDown = useCallback(
        (event, index: number) => {
            const keyMap = orientation === 'horizontal' ? HORIZONTAL_KEYS : VERTICAL_KEYS;
            const moveTo = keyMap[event.key as keyof typeof keyMap];

            if (moveTo) {
                const nextStep =
                    moveTo === 'prev'
                        ? getPrevStep({ stepStrategy, actualStep: index, steps })
                        : getNextStep({ stepStrategy, actualStep: index, steps, completedStepsRef });

                if (!isNil(nextStep)) {
                    event.preventDefault();
                    stepElementsRef.current[nextStep]?.focus();
                    if (autoSelect) {
                        navigateSteps(nextStep);
                    }
                }
            }

            if (SUBMIT_KEYS.includes(event.key)) {
                event.preventDefault();
                navigateSteps(index);
            }
        },
        [orientation, stepStrategy, steps, completedStepsRef, stepElementsRef, autoSelect, navigateSteps]
    );
    const stepsProps = useMemo(
        () =>
            steps.map((_step, index) => {
                const hashId = getIdByLabel(_step.label);
                const isLast = index === steps.length - 1;
                const stepsCountChanged = preStepsProps.current.length && steps.length !== preStepsProps.current.length;

                if (stepsCountChanged && preStepsProps.current[index]?.label !== _step.label) {
                    completedStepsRef.current = {
                        ...completedStepsRef.current,
                        [hashId]: false,
                    };
                }

                const isCompleted = completedStepsRef.current[hashId] || _step.completed;
                const nextStep = getNextStep({
                    stepStrategy,
                    actualStep,
                    steps,
                    completedStepsRef,
                });

                const uncompletedSteps = stepsToInclude.filter((step) => {
                    const hashId = getIdByLabel(step.label);
                    return !completedSteps[hashId];
                });

                const weight = getWeight({
                    isCompleted,
                    initialWeight,
                    totalWeight,
                    preStepsProps,
                    index,
                    uncompletedSteps,
                    includeOptional,
                    isOptional: _step.optional,
                });

                return {
                    key: index,
                    index,
                    weight,
                    role: 'tab',
                    'aria-selected': actualStep === index,
                    'aria-controls': `${stepperRef.current}-steps-${index}`,
                    tabIndex: actualStep === index ? 0 : -1,
                    id: stepId(stepperRef.current, index),
                    'aria-labelledby': `${stepperRef.current}-step-${index}`,
                    onKeyDown: (event: React.KeyboardEvent<HTMLElement>) => handleKeyDown(event, index),
                    ref: (el: any) => (stepElementsRef.current[index] = el),
                    disabled: _step.disabled,
                    isLast,
                    isNextDisabled: steps?.[index + 1]?.disabled,
                    completed: isCompleted,
                    onClick:
                        (!_step.disabled && stepStrategy === 'cyclic') ||
                        (isCompleted && stepStrategy === 'linear-back') ||
                        index === nextStep
                            ? () => {
                                  setStep(index);
                              }
                            : undefined,
                    label: _step.label,
                    optional: _step.optional,
                };
            }),
        [
            steps,
            completedStepsRef,
            stepStrategy,
            actualStep,
            stepsToInclude,
            includeOptional,
            stepperRef,
            completedSteps,
            handleKeyDown,
            setStep,
        ]
    );

    useEffect(() => {
        preStepsProps.current = stepsProps;
        totalWeight.current = 0;
        setCompletedSteps(completedStepsRef.current);
    }, [completedStepsRef, setCompletedSteps, stepsProps]);

    return {
        stepsProps,
    };
};

export default useStepsProps;
